async function info(input){const video=await input.getPrimaryVideoTrack();if(!video)throw new Error('No se encontró una pista de video. Carga una grabación MP4, MOV, WebM o MKV.');const audio=await input.getPrimaryAudioTrack();const duration=await input.computeDuration();if(!Number.isFinite(duration)||duration<=0)throw new Error('No se pudo leer la duración del video. Prueba con una grabación MP4 finalizada.');let fps=null;try{fps=(await video.computePacketStats(120)).averagePacketRate;}catch{}return {video,audio,meta:{duration,fps:Number.isFinite(fps)?fps:null,width:await video.getDisplayWidth(),height:await video.getDisplayHeight(),hasAudio:!!audio,audioTracks:(await input.getAudioTracks()).length,videoCodec:await video.getCodec(),canDecodeVideo:await video.canDecode(),canDecodeAudio:audio?await audio.canDecode():false}};}
