 if(audio&&meta.canDecodeAudio){progress('Escuchando la partida',1,true);try{const sink=new AudioSampleSink(audio);for await(const sample of sink.samples()){try{const data=new Float32Array(sample.allocationSize({format:'f32',planeIndex:0})/4);sample.copyTo(data,{format:'f32',planeIndex:0});const channels=sample.numberOfChannels;for(let f=0;f<sample.numberOfFrames;f+=8){const bin=Math.floor((sample.timestamp+f/sample.sampleRate)*2);if(bin<0||bin>=bins)continue;let energy=0;for(let ch=0;ch<channels;ch++)energy+=data[f*channels+ch]**2;energy/=channels;sums[bin]+=energy;counts[bin]++;}progress('Escuchando la partida',Math.min(42,sample.timestamp/meta.duration*42));}finally{sample.close();}}audioAvailable=true;}catch{warnings.push('No se pudo analizar el audio completo; las propuestas usan la imagen.');sums.fill(0);counts.fill(0);}}
 else if(audio)warnings.push('El códec de audio no se puede analizar en este navegador. Se utilizó la imagen.');else warnings.push('El video no tiene pista de audio; se utilizó la imagen.');
 const audioLevels=Array.from(sums,(n,i)=>counts[i]?Math.sqrt(n/counts[i]):0);progress('Buscando cambios de imagen',43,true);
 const interval=Math.max(1,meta.duration/3600),times=[];for(let t=0;t<meta.duration-.02;t+=interval){times.push(t);times.push(Math.min(meta.duration-.01,t+.16));}
 const sink=new CanvasSink(video,{width:96,height:54,fit:'fill',poolSize:1});let previous=null,index=0,validFrames=0;for await(const frame of sink.canvasesAtTimestamps(times)){const targetTime=times[index];if(frame){const pixels=frame.canvas.getContext('2d',{willReadFrequently:true}).getImageData(0,0,96,54).data;const gray=new Float32Array(96*54);for(let p=0;p<gray.length;p++)gray[p]=(pixels[p*4]*.299+pixels[p*4+1]*.587+pixels[p*4+2]*.114)/255;
 if(index%2===1&&previous){let difference=0;for(let p=0;p<gray.length;p++)difference+=Math.abs(gray[p]-previous[p]);difference/=gray.length;const start=Math.floor(times[index-1]*2),end=Math.min(bins,Math.ceil((times[index-1]+interval)*2));for(let b=start;b<end;b++)motion[b]=difference;validFrames++;}previous=index%2===0?gray:null;}else previous=null;index++;progress('Buscando cambios de imagen',43+index/times.length*48);}
