 if(motionApplied){const probeA=new OffscreenCanvas(48,27).getContext('2d',{willReadFrequently:true}),probeB=new OffscreenCanvas(48,27).getContext('2d',{willReadFrequently:true});mixer=new FrameMixer(new VideoSampleSink(video).samples(clip.start,clip.end),(a,b)=>{a.draw(probeA,0,0,48,27);b.draw(probeB,0,0,48,27);const p=probeA.getImageData(0,0,48,27).data,q=probeB.getImageData(0,0,48,27).data;let difference=0;for(let i=0;i<p.length;i+=4)difference+=Math.abs(p[i]-q[i])+Math.abs(p[i+1]-q[i+1])+Math.abs(p[i+2]-q[i+2]);return difference/(48*27*3*255);});}
