 if(!conversion.isValid||!conversion.utilizedTracks.includes(video)||(audio&&s.volume>0&&!conversion.utilizedTracks.includes(audio)))throw new Error('El navegador no pudo preparar todas las pistas de video y audio. No se creó un archivo incompleto. Prueba otro formato o una resolución menor.');
