self.onmessage=async({data})=>{let input;try{input=new Input({source:new BlobSource(data.file),formats:ALL_FORMATS});let result;if(data.action==='analyze')result=await analyze(input,data.options);else if(data.action==='inspect'){const {video,meta}=await info(input);result={meta,thumbs:meta.canDecodeVideo?await thumbnails(video,[{start:Math.min(1,meta.duration*.1)}]):[]};}else if(data.action==='thumbnails'){const {video}=await info(input);result={thumbs:await thumbnails(video,data.clips)};}else if(data.action==='export')result=await exportClip(input,data);else throw new Error('Operación desconocida.');if(result.buffer)postMessage({type:'result',result},[result.buffer]);else postMessage({type:'result',result});}catch(error){postMessage({type:'error',message:exportStorageError(error,data.destination)});}finally{input?.dispose();}};
